package diag;
import static diag.Observe.*;
import java.io.*;import java.lang.instrument.*;import java.nio.file.*;import java.security.ProtectionDomain;import java.util.*;
import jdk.internal.org.objectweb.asm.*;import jdk.internal.org.objectweb.asm.commons.AdviceAdapter;
public final class PlanObserve {
 static final String TARGET="BenchmarkTest01000$Test#doSomething";
 public static void premain(String path,Instrumentation inst)throws Exception{
  output=new PrintWriter(Files.newBufferedWriter(Path.of(path)));
  Runtime.getRuntime().addShutdownHook(new Thread(()->{synchronized(Observe.class){output.println("{\"event\":\"END\",\"rows\":"+rows+",\"errors\":"+errors+"}");output.close();}}));
  inst.addTransformer(new ClassFileTransformer(){public byte[] transform(ClassLoader cl,String cn,Class<?> r,ProtectionDomain pd,byte[]bytes){boolean cp=cn.equals("org/opentaint/dataflow/jvm/bidi/interp/JIRCallPlanBuilder"),sp=cn.equals("org/opentaint/dataflow/jvm/bidi/interp/JIRStatementForms");if(!cp&&!sp)return null;
   try{ClassReader cr=new ClassReader(bytes);ClassWriter cw=new ClassWriter(cr,ClassWriter.COMPUTE_MAXS);cr.accept(new ClassVisitor(Opcodes.ASM8,cw){public MethodVisitor visitMethod(int acc,String name,String desc,String sig,String[]ex){MethodVisitor mv=super.visitMethod(acc,name,desc,sig,ex);if(!name.equals("build"))return mv;return new AdviceAdapter(Opcodes.ASM8,mv,acc,name,desc){protected void onMethodExit(int op){if(op==ARETURN){dup();loadThis();if(sp)loadArg(0);else visitInsn(ACONST_NULL);visitMethodInsn(INVOKESTATIC,"diag/PlanObserve","capture","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false);}}};}},ClassReader.EXPAND_FRAMES);System.err.println("PLAN_TRANSFORM "+cn);return cw.toByteArray();}catch(Throwable t){error("transform",t);return null;}
  }});
 }
 static Object pattern(Object fact,Object e)throws Exception{return Class.forName("org.opentaint.dataflow.bidi.ap.Pattern").getConstructors()[0].newInstance(fact,e);}
 static Object event(Object ap,String ev,Object method,Object inst)throws Exception{Object b=builder(ap,ev,0,String.valueOf(method),"FORWARD_FORM");call(b,"text","statement",String.valueOf(inst));call(b,"number","instruction",get(get(inst,"location"),"index"));return b;}
 static void summary(Object ap,Object method,Object inst,String stage,Object summary)throws Exception{
  Object b=event(ap,"FORM_HEADER",method,inst);call(b,"text","stage",stage);for(String k:new String[]{"sources","conjunctions","staticOperations","touched","typeFilters","resultFilters"}){Object v=get(summary,k);call(b,"number",k,v instanceof Collection?((Collection<?>)v).size():((Map<?,?>)v).size());}call(b,"text","touchedValues",String.valueOf(get(summary,"touched")));emit(b);
  int n=0;for(Object me:(Collection<?>)get(summary,"edges")){
   Object e=get(me,"edge");Object c=event(ap,"FORM_EDGE",method,inst);call(c,"text","stage",stage);call(c,"number","ordinal",n++);call(c,"pattern","from",pattern(get(e,"from"),get(e,"fromExclusion")));call(c,"pattern","to",pattern(get(e,"to"),get(e,"toExclusion")));call(c,"text","sharedExclusion",String.valueOf(get(e,"exclusion")));call(c,"flag","may",get(me,"may"));call(c,"flag","conjunctive",get(me,"conjunctive"));call(c,"text","actionId",String.valueOf(get(me,"actionId")));emit(c);
  }
 }
 public static void capture(Object value,Object factory,Object suppliedInst){try{
  Object ap=field(factory,"manager"),inst=suppliedInst,method;
  if(inst==null){inst=field(factory,"s");method=field(factory,"caller");}else method=get(get(inst,"location"),"method");
  if(!String.valueOf(method).contains(TARGET))return;
  if(suppliedInst!=null){summary(ap,method,inst,"STATEMENT",value);return;}
  Object b=event(ap,"PLAN_HEADER",method,inst);call(b,"number","sinks",((Collection<?>)get(value,"sinks")).size());call(b,"text","entry",String.valueOf(get(value,"entry")));call(b,"text","exit",String.valueOf(get(value,"exit")));emit(b);
  int n=0;for(Object st:(Collection<?>)get(value,"stages")){
   String name=st.getClass().getSimpleName(),label=n+++":"+name;Object c=event(ap,"PLAN_STAGE",method,inst);call(c,"text","stage",label);call(c,"text","from",String.valueOf(get(st,"from")));call(c,"text","to",String.valueOf(get(st,"to")));
   if(name.equals("Edges")){call(c,"text","kind",String.valueOf(get(st,"kind")));call(c,"text","guard",String.valueOf(get(st,"guard")));emit(c);summary(ap,method,inst,label,get(st,"summary"));}
   else if(name.equals("Actions")){call(c,"text","steps",String.valueOf(get(st,"steps")));emit(c);}
   else if(name.equals("Callees")){call(c,"text","callees",String.valueOf(get(st,"callees")));emit(c);}
   else{call(c,"text","payload",String.valueOf(st));emit(c);}
  }
  synchronized(Observe.class){output.flush();}
 }catch(Throwable t){error("capture",t);}}
}

