package diag;

import java.io.*;
import java.lang.instrument.*;
import java.lang.reflect.*;
import java.nio.file.*;
import java.security.ProtectionDomain;
import java.util.*;
import jdk.internal.org.objectweb.asm.*;
import jdk.internal.org.objectweb.asm.commons.AdviceAdapter;

/** Observational only: copies joined stores and completed forward witnesses. */
public final class Observe {
  static PrintWriter output;
  static long errors, rows;
  public static void premain(String path, Instrumentation inst) throws Exception {
    output=new PrintWriter(Files.newBufferedWriter(Path.of(path)));
    Runtime.getRuntime().addShutdownHook(new Thread(()->{
      synchronized(Observe.class){output.println("{\"event\":\"END\",\"rows\":"+rows+",\"errors\":"+errors+"}");output.close();}
    }));
    inst.addTransformer(new ClassFileTransformer(){
      public byte[] transform(ClassLoader loader,String name,Class<?> redef,ProtectionDomain domain,byte[] bytes){
        boolean hand=name.equals("org/opentaint/dataflow/bidi/driver/HandOff$Companion");
        boolean wit=name.equals("org/opentaint/dataflow/bidi/engine/RunMethodLocalServices");
        if(!hand&&!wit)return null;
        try { System.err.println("OBSERVE_TRANSFORM "+name); ClassReader reader=new ClassReader(bytes);ClassWriter writer=new ClassWriter(reader,ClassWriter.COMPUTE_MAXS);
        reader.accept(new ClassVisitor(Opcodes.ASM8,writer){
          public MethodVisitor visitMethod(int access,String method,String desc,String sig,String[] exceptions){
            MethodVisitor delegate=super.visitMethod(access,method,desc,sig,exceptions);
            if(hand&&method.equals("of"))return new AdviceAdapter(Opcodes.ASM8,delegate,access,method,desc){
              protected void onMethodExit(int opcode){if(opcode==ARETURN){dup();loadArg(0);loadArg(1);loadArg(2);
                visitMethodInsn(INVOKESTATIC,"diag/Observe","handoff","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false);}}
            };
            if(wit&&method.equals("witness"))return new AdviceAdapter(Opcodes.ASM8,delegate,access,method,desc){
              public void visitMethodInsn(int op,String owner,String mn,String md,boolean itf){
                super.visitMethodInsn(op,owner,mn,md,itf);
                if(owner.endsWith("/ReportCatalog")&&mn.startsWith("internReached")){
                  dup();loadArg(0);loadArg(1);loadArg(2);loadArg(3);
                  super.visitMethodInsn(INVOKESTATIC,"diag/Observe","witness","(ILjava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false);
                }
              }
            };
            return delegate;
          }
        },ClassReader.EXPAND_FRAMES);
        return writer.toByteArray(); } catch(Throwable t) { error("transform:"+name,t);return null;}
      }
    });
  }
  static Object field(Object o,String name)throws Exception{
    for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException e){}
    throw new NoSuchFieldException(o.getClass()+"."+name);
  }
  static Method method(Object o,String name,int n)throws Exception{
    for(Method m:o.getClass().getMethods())if((m.getName().equals(name)||m.getName().startsWith(name+"$")||m.getName().startsWith(name+"-"))&&m.getParameterCount()==n){m.setAccessible(true);return m;}
    throw new NoSuchMethodException(o.getClass()+"."+name+"/"+n);
  }
  static Object call(Object o,String name,Object...args)throws Exception{return method(o,name,args.length).invoke(o,args);}
  static Object get(Object o,String name)throws Exception{return call(o,"get"+Character.toUpperCase(name.charAt(0))+name.substring(1));}
  static Iterable<?> sequence(Object seq)throws Exception{
    Iterator<?> iter=(Iterator<?>)call(seq,"iterator");List<Object> out=new ArrayList<>();iter.forEachRemaining(out::add);return out;
  }
  static Object builder(Object ap,String event,int run,String owner,String scope)throws Exception{
    Class<?> type=Class.forName("org.opentaint.dataflow.bidi.engine.LoopPipelineTrace$Fields");
    Constructor<?> c=type.getDeclaredConstructor(int.class,int.class);c.setAccessible(true);Object b=c.newInstance(1024*1024,65536);
    call(b,"catalog",ap);call(b,"text","event",event);call(b,"number","run",run);call(b,"text","method",owner);call(b,"text","scope",scope);return b;
  }
  static synchronized void emit(Object b)throws Exception{output.println(call(b,"finish"));rows++;}
  static synchronized void error(String phase,Throwable t){errors++;output.println("{\"event\":\"ERROR\",\"phase\":\""+phase+"\",\"message\":\""+String.valueOf(t).replace("\\","\\\\").replace("\"","\\\"").replace("\n"," ")+"\"}");output.flush();t.printStackTrace(System.err);}
  public static void witness(int id,Object core,Object sink,Object node,Object edges){
    try{
      int run=((Number)get(get(core,"config"),"index")).intValue();if(run<5)return;
      Object b=builder(get(core,"ap"),"WITNESS",run,String.valueOf(get(core,"key")),String.valueOf(get(core,"scope")));
      call(b,"number","reportId",id);call(b,"text","sinkRule",String.valueOf(get(get(sink,"rule"),"id")));call(b,"text","statement",String.valueOf(node));
      int i=0;for(Object edge:(List<?>)edges){call(b,"premise","premise"+i,get(edge,"premise"));call(b,"facts","facts"+i,get(edge,"facts"));call(b,"text","layer"+i,String.valueOf(get(edge,"layer")));i++;}
      call(b,"number","inputs",i);emit(b);
    }catch(Throwable t){error("witness",t);}
  }
  static void dataRows(Object ap,int run,Object owner,String scope,List<?> rows,List<?> ports)throws Exception{
    int idx=0;for(Object row:rows){Object b=builder(ap,"DEMAND_DATA",run,String.valueOf(owner),scope);
      call(b,"pattern","entry",get(row,"entry"));Object exit=get(row,"exit");if(exit!=null)call(b,"pattern","exit",exit);
      if(ports!=null)call(b,"text","port",String.valueOf(ports.get(idx)));emit(b);idx++;}
  }
  static void control(Object ap,int run,Object owner,String scope,Object row,Object port)throws Exception{
    Object b=builder(ap,"DEMAND_CONTROL",run,String.valueOf(owner),scope);
    if(port!=null)call(b,"text","port",String.valueOf(port));
    for(String key:new String[]{"entry","exit"}){Object end=get(row,key);call(b,"text",key+"Kind",end.getClass().getSimpleName());
      if(end.getClass().getSimpleName().equals("Data"))call(b,"pattern",key,get(end,"pattern"));}
    emit(b);
  }
  static void summaries(Object ap,int run,Object key,String scope,Object store)throws Exception{
    for(Object pair:sequence(call(store,"all"))){Object b=builder(ap,"CURRENT_SUMMARY",run,String.valueOf(key),scope);
      call(b,"premise","premise",get(pair,"first"));call(b,"facts","facts",get(pair,"second"));emit(b);}
  }
  static void targets(Object ap,int run,Object key,String scope,Collection<?> targets)throws Exception{
    for(Object row:targets){Object b=builder(ap,"TARGET",run,String.valueOf(key),scope);call(b,"premise","premise",get(row,"premise"));
      call(b,"text","target",String.valueOf(get(row,"target")));emit(b);}
  }
  public static void handoff(Object hand,Object config,Object result,Object shared){
    try{
      int run=((Number)get(config,"index")).intValue();if(run<5)return;
      Object ap=get(shared,"ap"),ds=get(hand,"demand");
      for(var e:((Map<?,?>)field(ds,"byMethod")).entrySet())dataRows(ap,run,e.getKey(),"ROOT",(List<?>)field(e.getValue(),"rows"),null);
      for(var e:((Map<?,?>)field(ds,"controls")).entrySet())for(Object row:(List<?>)e.getValue())control(ap,run,e.getKey(),"ROOT",row,null);
      for(var e:((Map<?,?>)field(ds,"scoped")).entrySet()){
        Object key=get(e.getKey(),"method"),scope=get(e.getKey(),"local"),si=e.getValue();
        dataRows(ap,run,key,String.valueOf(scope),(List<?>)field(field(si,"data"),"rows"),(List<?>)field(si,"rowPorts"));
        for(Object pair:(List<?>)field(si,"controls"))control(ap,run,key,String.valueOf(scope),get(pair,"second"),get(pair,"first"));
      }
      for(Object zero:sequence(call(get(config,"normalTargets"),"zeroRows"))){Object b=builder(ap,"CONFIRMED",run,String.valueOf(get(zero,"method")),"ROOT");call(b,"number","reportId",get(zero,"id"));emit(b);}
      for(Object actor:(List<?>)get(result,"analyzers")){
        Object key=get(actor,"key");targets(ap,run,key,"ROOT",(Collection<?>)get(actor,"outgoingTargets"));
        for(Object block:sequence(call(actor,"blockOutgoingTargets")))targets(ap,run,key,String.valueOf(get(block,"scope"))+" exit="+get(block,"exit"),(Collection<?>)get(block,"rows"));
        summaries(ap,run,key,"ROOT",get(actor,"summaries"));
        for(Object block:sequence(call(actor,"blockSummaries")))summaries(ap,run,key,String.valueOf(get(get(block,"key"),"scope"))+" exit="+get(get(block,"key"),"exit"),get(block,"summaries"));
      }
      Object seeds=get(hand,"seeds");for(Object list:((Map<?,?>)field(seeds,"byPlace")).values())for(Object seed:(List<?>)list){
        Object b=builder(ap,"SEED",run,String.valueOf(get(seed,"method")),"");call(b,"text","seedKind",seed.getClass().getSimpleName());
        call(b,"text","statement",String.valueOf(get(seed,"statement")));call(b,"text","value",String.valueOf(seed));
        if(seed.getClass().getSimpleName().equals("Sink"))call(b,"pattern","requirement",get(seed,"requirement"));emit(b);
      }
      Object b=builder(ap,"HANDOFF_END",run,"","");call(b,"number","explicitRows",((Map<?,?>)get(hand,"demandEdges")).values().stream().mapToInt(v->((Number)v).intValue()).sum());emit(b);
      synchronized(Observe.class){output.flush();}
    }catch(Throwable t){error("handoff",t);}
  }
}

